begin;
create or replace function platform_private.enqueue_notification_core(p_event_type text,p_module_key text,p_resource_type text,p_resource_id text,p_scope_type text,p_scope_id text,p_title text,p_body text,p_target_url text,p_dedupe_key text) returns jsonb language plpgsql security definer set search_path='' as $$declare event_id uuid;inserted boolean:=false;delivery_count integer;recipient_count integer;begin if p_module_key not in('conference','reservations','warehouse','platform') or p_event_type !~ '^[a-z0-9_.-]{3,120}$' or p_resource_type !~ '^[a-z0-9_.-]{1,80}$' or ((p_scope_type is null)<>(p_scope_id is null)) or (p_scope_type is not null and p_scope_type !~ '^[a-z0-9_.-]{1,80}$') or (p_module_key='reservations' and (p_scope_type is distinct from 'event' or p_scope_id is null)) or char_length(coalesce(p_title,'')) not between 1 and 160 or char_length(coalesce(p_body,'')) not between 1 and 500 or char_length(coalesce(p_target_url,'')) not between 1 and 1000 or char_length(coalesce(p_dedupe_key,'')) not between 1 and 240 then raise exception 'PLATFORM_NOTIFICATION_EVENT_INVALID' using errcode='22023';end if;insert into platform.notification_events(event_type,module_key,resource_type,resource_id,scope_type,scope_id,title,body,target_url,dedupe_key)values(p_event_type,p_module_key,p_resource_type,p_resource_id,p_scope_type,p_scope_id,p_title,p_body,p_target_url,p_dedupe_key)on conflict(dedupe_key)do nothing returning id into event_id;if event_id is null then select id into event_id from platform.notification_events where dedupe_key=p_dedupe_key;else inserted:=true;end if;insert into platform.notification_recipients(notification_event_id,user_id)select event_id,pr.user_id from platform.profiles pr where platform_private.notification_user_is_authorized(pr.user_id,p_module_key,p_scope_type,p_scope_id)on conflict do nothing;get diagnostics recipient_count=row_count;insert into platform.notification_deliveries(notification_event_id,subscription_id)select event_id,s.id from platform.notification_push_subscriptions s join platform.notification_recipients r on r.notification_event_id=event_id and r.user_id=s.user_id where platform_private.notification_subscription_is_authorized(s.id,p_module_key,p_scope_type,p_scope_id)on conflict(notification_event_id,subscription_id)do nothing;get diagnostics delivery_count=row_count;return jsonb_build_object('notificationEventId',event_id,'created',inserted,'recipients',recipient_count,'queuedDeliveries',delivery_count);end$$;
revoke all on function platform_private.enqueue_notification_core(text,text,text,text,text,text,text,text,text,text) from public,anon,authenticated,service_role;
create or replace function platform_private.enqueue_notification(p_event_type text,p_module_key text,p_resource_type text,p_resource_id text,p_scope_type text,p_scope_id text,p_title text,p_body text,p_target_url text,p_dedupe_key text) returns jsonb language plpgsql security definer set search_path='' as $$begin if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'PLATFORM_NOTIFICATION_BACKEND_REQUIRED' using errcode='42501';end if;return platform_private.enqueue_notification_core(p_event_type,p_module_key,p_resource_type,p_resource_id,p_scope_type,p_scope_id,p_title,p_body,p_target_url,p_dedupe_key);end$$;
revoke all on function platform_private.enqueue_notification(text,text,text,text,text,text,text,text,text,text) from public,anon,authenticated;grant execute on function platform_private.enqueue_notification(text,text,text,text,text,text,text,text,text,text) to service_role;
create or replace function platform_private.stage_public_registration_request_notification() returns trigger language plpgsql security definer set search_path='' as $$declare v_public_id uuid;begin select c.public_id into v_public_id from reservations.public_registration_channels c where c.id=new.channel_id and c.event_id=new.event_id;if v_public_id is null then raise exception 'PUBLIC_REGISTRATION_NOTIFICATION_SCOPE_INVALID' using errcode='42501';end if;perform platform_private.stage_public_registration_submitted_notification(new.id,new.event_id,new.request_reference,v_public_id,new.submit_operation_id);return new;end$$;
revoke all on function platform_private.stage_public_registration_request_notification() from public,anon,authenticated,service_role;
create trigger public_registration_request_notification_outbox after insert on reservations.public_registration_requests for each row execute function platform_private.stage_public_registration_request_notification();
commit;